"""System prompts: presets plus the Workbench context generated by llm-context."""
import os
import re
from datetime import datetime
from pathlib import Path
from typing import Dict, List, Optional

USER_HOME = Path(os.environ.get("APP_USER_HOME", "/home/nemotron"))
CONTEXT_FILE = USER_HOME / ".claude" / "CLAUDE.md"
DATA_DIR = Path(os.environ.get("DATA_DIR", "/data"))
# User-maintained data dictionary notes (visit codes, units, flag meanings).
# A data dictionary was the single biggest accuracy gain for Nemotron in eval-bench.
NOTES_FILE = DATA_DIR / "data_notes.md"
MAX_NOTES_CHARS = 20000
SKILLS_DIR = USER_HOME / ".claude" / "skills"
# ~10K tokens; the full file is larger because of a machine-readable JSON dump.
MAX_CONTEXT_CHARS = 40000

PRESETS: Dict[str, Dict[str, object]] = {
    "workbench": {
        "label": "Workbench agent",
        "tools": True,
        "context": True,
        "persona": "You are a capable research assistant working inside the user's Verily Workbench workspace.",
    },
    "analyst": {
        "label": "Data analyst",
        "tools": True,
        "context": True,
        "persona": (
            "You are a careful biomedical data analyst. Explore schemas before querying, state assumptions, "
            "check row counts and missingness, and present results as tables and charts."
        ),
    },
    "sql": {
        "label": "SQL expert",
        "tools": True,
        "context": True,
        "persona": (
            "You are a BigQuery SQL expert. Write correct, efficient Standard SQL with fully qualified table "
            "names, inspect schemas first, and put final queries in sql artifacts."
        ),
    },
    "plain": {
        "label": "Plain chat (no tools)",
        "tools": False,
        "context": False,
        "persona": "You are a helpful assistant.",
    },
}

TOOL_GUIDE = """\
## How to work
- You have tools for this workspace. Use them to look things up instead of guessing, and never invent tool results.
- Call one tool at a time when later steps depend on earlier results. Read every error and change your call; never repeat a call that failed.
- If no current tool fits, call find_tools with keywords; matching tools become available.
- Workbench skill guides are available via list_skills / read_skill (instead of reading ~/.claude/skills files).
- Deleting or removing anything requires the user's approval, which the app requests automatically. If the user denies, do not retry.

## Querying BigQuery
1. Find tables with list_tables, then call describe_table on every table you will query. Use only column names it returns; never guess names like participant_id or USUBJID.
2. Always write tables as `project.dataset.table` in backticks, e.g. `my-project.my_dataset.my_table` (describe_table prints the exact name). `project.table` without the dataset fails.
3. Run SQL only with run_sql (never through bq_execute, wb_execute or gcloud_execute: shells break backticks).
4. Use the value hints: filter on the exact category values shown (e.g. VISIT = 'STUDY_START', not VISITNUM = 1), treat 0/1 flags as `= 1` (not IS NOT NULL), and check units in descriptions (durations may be milliseconds).
5. When documentation and data disagree, trust the data: verify a category or unit with SELECT DISTINCT or MIN/MAX before relying on it.
6. BigQuery dialect: UNION ALL / UNION DISTINCT (never bare UNION); APPROX_QUANTILES(x, 2)[OFFSET(1)] or PERCENTILE_CONT(x, 0.5) OVER () instead of MEDIAN; STRING_AGG not GROUP_CONCAT; LOGICAL_OR / LOGICAL_AND not BOOL_OR; REGEXP_CONTAINS for regex; SAFE_CAST to convert types; DATE_DIFF(a, b, DAY).
7. Before answering, sanity-check: do row counts match expectations? Did `!=` or NOT IN silently drop NULL rows? Should a join be LEFT JOIN to keep everyone in the denominator?

## Canvas artifacts
Put substantial outputs in the canvas with create_artifact instead of pasting them into chat:
- markdown: reports, summaries, plans.
- sql: final queries. The user can run them from the canvas.
- chart: a JSON spec. Use Vega-Lite (with "$schema": "https://vega.github.io/schema/vega-lite/v5.json") or Plotly ({"data": [...], "layout": {...}}). Inline the data values you got from run_sql.
- html: a single self-contained HTML document (inline CSS/JS; CDN script tags are allowed). It runs in a sandbox and can call `await workbench.query("SELECT ...")`, which resolves to {columns:[{name,type}], rows:[[...]], total_rows}. Only SELECT queries are allowed from mini-apps.
- code / csv: scripts and tabular data.
To change an artifact, call update_artifact with its id and the full new content. Then briefly tell the user what you made.
"""


def context_status() -> Dict[str, object]:
    if CONTEXT_FILE.exists():
        stat = CONTEXT_FILE.stat()
        return {
            "available": True,
            "chars": stat.st_size,
            "generated_at": datetime.fromtimestamp(stat.st_mtime).isoformat(timespec="seconds"),
        }
    return {"available": False, "chars": 0, "generated_at": None}


def workspace_context() -> Optional[str]:
    try:
        text = CONTEXT_FILE.read_text(errors="replace")
    except OSError:
        return None
    # The trailing JSON block repeats the resource table in machine-readable
    # form; drop it when space is tight.
    if len(text) > MAX_CONTEXT_CHARS:
        text = re.sub(r"## Quick Reference \(Machine-Readable\).*?(?=\n## |\Z)", "", text, flags=re.S)
    if len(text) > MAX_CONTEXT_CHARS:
        text = text[:MAX_CONTEXT_CHARS] + "\n… [workspace context truncated]"
    return text


def system_prompt(preset: str, custom: str = "", tools_enabled: bool = True) -> str:
    p = PRESETS.get(preset, PRESETS["workbench"])
    parts: List[str] = [str(p["persona"])]
    parts.append(f"Today is {datetime.now().strftime('%Y-%m-%d')}. You run on self-hosted NVIDIA Nemotron models; no data leaves the workspace.")
    if p["tools"] and tools_enabled:
        parts.append(TOOL_GUIDE)
    if p["context"]:
        ctx = workspace_context()
        if ctx:
            parts.append("# Workspace context\n" + ctx)
        else:
            parts.append("(Workspace context is not available yet; use tools such as workspace_get and resource_list_tree.)")
    notes = read_notes()
    if notes.strip() and p["context"]:
        parts.append("# Data notes from the user (trust these over your assumptions)\n" + notes.strip()[:MAX_NOTES_CHARS])
    if custom.strip():
        parts.append("# Additional instructions from the user\n" + custom.strip())
    return "\n\n".join(parts)


def list_skills() -> List[str]:
    if not SKILLS_DIR.exists():
        return []
    return sorted(str(p.relative_to(SKILLS_DIR).with_suffix("")) for p in SKILLS_DIR.rglob("*.md"))


def read_skill(name: str) -> str:
    name = name.strip().removesuffix(".md").removeprefix("~/.claude/skills/")
    path = (SKILLS_DIR / f"{name}.md").resolve()
    if SKILLS_DIR.resolve() not in path.parents or not path.exists():
        # Allow case-insensitive and basename matches.
        matches = [s for s in list_skills() if s.lower() == name.lower() or s.lower().endswith("/" + name.lower())]
        if not matches:
            raise FileNotFoundError(f"No skill named {name!r}. Available: {', '.join(list_skills())}")
        path = SKILLS_DIR / f"{matches[0]}.md"
    return path.read_text(errors="replace")


def read_notes() -> str:
    try:
        return NOTES_FILE.read_text(errors="replace")
    except OSError:
        return ""


def write_notes(text: str):
    NOTES_FILE.parent.mkdir(parents=True, exist_ok=True)
    NOTES_FILE.write_text(text)
